from __future__ import annotations
from openclass_core.models import AgentActivityEvent, BoardDecision, ChatResponse, CoursePackage, LearningClarificationStatus, SourceCitation
from openclass_core.services.lesson_factory import build_requirements

def build_source_qa_response(*, lesson_title: str, course_package: CoursePackage, chatbot_message: str, citations: list[SourceCitation], follow_up_suggestions: list[str], agent_activity: list[AgentActivityEvent], clarification: LearningClarificationStatus, preserved_state: dict[str, object] | None=None) -> ChatResponse:
    return ChatResponse(chatbot_message=chatbot_message, source_citations=citations, follow_up_suggestions=follow_up_suggestions, agent_activity=agent_activity, learning_requirement_sheet=build_requirements(lesson_title), active_requirement_sheet=None, learning_clarification=clarification, board_task_sheet=None, active_board_task_sheet=None, board_task_questions=[], board_decision=BoardDecision(action='no_change', reason='The turn answered from an authenticated source scope without changing the board.'), needs_clarification=False, clarification_questions=[], requirement_cleared=False, board_document_operation_status='none', course_package=course_package).model_copy(update=preserved_state or {})

def build_existing_board_response(*, lesson_title: str, course_package: CoursePackage, chatbot_message: str, follow_up_suggestions: list[str], agent_activity: list[AgentActivityEvent], clarification: LearningClarificationStatus, changed: bool, no_change_reason: str, changed_reason: str) -> ChatResponse:
    return ChatResponse(chatbot_message=chatbot_message, follow_up_suggestions=follow_up_suggestions, agent_activity=agent_activity, learning_requirement_sheet=build_requirements(lesson_title), active_requirement_sheet=None, learning_clarification=clarification, board_task_sheet=None, active_board_task_sheet=None, board_task_questions=[], board_decision=BoardDecision(action='edit_board' if changed else 'no_change', reason=changed_reason if changed else no_change_reason), needs_clarification=False, clarification_questions=[], requirement_cleared=True, board_document_operation_status='succeeded' if changed else 'none', course_package=course_package)
